import React, { useState } from 'react';
import { Paginator } from 'primereact/paginator';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="paginator-accessibility">Accessible Paginator</label>
            <Paginator 
                id="paginator-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible Paginator input"
                placeholder="Enter paginator"
            />
        </div>
    );
}